\u0039\u002d\u004d\u0040\u0074\u003b\u004c\u0035\u0040\u0049\u0044\u0046\u0076\u0034\u007b\u0051\u004d\u0048\u0077\u0038\u0054\u007a\u002b\u0068\u0071\u0073\u0066\u007c\u003d\u0055\u0048\u0056\u004e\u0073\u0029\u002f\u004b\u007b\u0056\u007b\u004f\u0058\u004d\u0078\u002a\u0032\u006a\u0053\u006e\u0069\u0036\u0049\u002c\u0029\u0054\u0026\u007c\u0035\u0075\u006c\u0046\u0049\u0070\u0031\u0055\u0029\u007a\u0041\u004a\u0050\u005b\u0035\u0058\u0034\u0025\u0058\u002e\u003f\u0066\u0049\u006a\u003e\u0071\u0053\u0043\u0072\u003a\u0046\u0025\u005e\u0025\u0072\u005b\u0055\u0065\u0031\u004a\u0075\u0077\u0073\u006c\u004a\u0034\u0078\u0055\u0036\u005b\u006f\u0026\u0039\u0053\u0065\u005b\u0073\u0071\u005f\u005d\u0051\u007c\u005c\u0062\u0068\u002a\u0039\u0036\u003a\u005d\u0060\u005e\u0050\u0040\u004e\u0030\u004e\u005c\u006a\u0042\u0050\u0067\u0037\u0038\u006c\u0048\u002b\u002c\u005c\u007a\u0040\u0039\u0079\u004d\u0039\u0031\u0073\u0044\u0070\u0039\u005b\u002a\u005c\u0048\u0068\u002c\u0021\u0027\u0074\u0057\u002b\u0022\u007d\u0059\u004a\u005f\u007c\u0043\u0075\u003b\u0057\u006b\u0057\u003d\u0030\u0045\u007a\u0029\u0057\u0049\u0078\u004a\u005f\u004d\u002e\u003e\u0068\u0058\u0027\u002b\u006b\u0050\u002e\u006e\u0071\u0064\u003f\u0056\u003d\u0028\u0074\u0040\u0072\u0077\u0040\u0066\u002a\u0062\u0033\u0051\u0074\u004c\u0041\u006b\u0038\u0061\u0056\u0025\u0026\u006a\u0027\u004b\u004d\u002d\u0077\u0036\u0053\u005b\u006d\u0067\u002a\u0071\u006a\u005e\u0056\u0046\u0049\u0032\u003f\u0062\u007e\u0025\u0051\u0058\u0021\u004b\u0032\u0037\u004f\u0077\u007b\u0076\u003a\u0036\u003f\u0044\u0053\u0048\u003e\u0073\u0035\u002b\u0057\u002d\u0027\u002f\u005b\u0042\u003e\u0069\u0046\u0037\u003f\u006e\u002f\u003b\u002e\u0035\u0057\u0029\u0044\u0026\u002c\u006b\u0071\u0050\u003c\u0051\u0022\u0079\u0067\u0023\u0055\u006f\u0059\u005b\u0070\u0039\u006e\u0074\u005e\u0034\u0076\u0057\u005e\u0046\u0073\u0038\u0036\u005d\u0062\u0039\u0040\u006c\u0035\u0029\u0037\u006f\u0050\u002b\u0054\u0069\u006b\u006e\u0023\u004a\u002a\u004d\u0069\u0033\u0035\u0045\u005a\u0052\u0074\u0051\u002a\u0060\u002c\u0062\u0074\u0071\u002d\u0043\u005f\u0059\u0079\u0038\u003f\u0029\u0063\u0033\u0041\u005f\u003a\u0048\u0047\u007c\u0051\u0028\u0037\u002e\u004f\u0070\u003e\u007d\u0059\u0022\u005e\u0037\u006f\u004d\u0062\u0071\u0061\u004f\u0065\u002a\u0054\u0077\u0074\u0048\u005a\u007c\u0064\u0062\u006f\u0072\u0068\u0040\u0020\u0026\u0046\u0021\u004e\u002a\u007d\u0063\u0022\u0054\u007c\u0075\u0024\u0048\u0070\u007e\u003a\u002f\u005e\u006b\u0051\u0022\u004a\u005a\u0032\u0060\u002d\u0045\u0062\u0071\u0058\u003b\u0058\u0023\u0045\u0029\u0024\u0071\u006e\u004c\u005c\u0052\u0073\u0036\u0036\u004d\u0067\u006a\u003f\u004d\u0063\u004d\u0037\u0067\u0034\u0021\u0065\u006f\u005a\u0078\u003a\u0076\u002e\u007c\u0062\u0055\u0029\u0031\u006f\u0079\u0043\u006c\u0063\u0060\u0073\u003b\u0041\u0051\u007b\u0064\u0041\u0067\u007d\u005f\u0022\u0028\u0069\u0054\u007d\u005c\u005e\u004c\u002d\u0047\u002d\u005b\u003f\u0056\u007e\u003e\u0036\u0020\u005f\u005c\u0023\u0064\u007d\u0027\u0023\u002d\u007b\u0025\u0052\u0051\u0063\u002e\u004b\u005d\u0050\u0049\u0060\u0041\u005a\u0032\u0038\u004e\u0049\u0076\u007d\u005c\u0078\u0036\u0054\u0044\u004d\u0073\u0074\u0067\u0032\u0065\u0041\u0048\u0064\u0025\u0039\u003b\u0029\u0070\u0028\u0073\u0026\u005f\u0048\u0075\u0026\u0067\u0048\u0072\u0053\u005d\u0073\u0025\u0027\u005b\u0069\u0051\u003b\u0039\u006f\u007a\u0051\u0079\u002a\u0030\u006a\u004e\u0027\u0027\u0034\u0062\u0069\u005d\u0062\u0030\u0070\u0062\u004d\u0031\u003e\u004b\u005f\u002a\u0065\u0076\u005e\u0040\u0061\u0023\u0073\u002d\u004c\u0067\u005c\u007e\u0045\u0054\u0021\u004e\u0032\u0038\u0070\u0052\u006f\u0022\u0032\u0064\u003e\u0020\u007d\u006c\u0020\u0061\u0028\u0073\u0042\u0057\u0023\u0036\u007e\u0032\u0067\u0070\u0078\u007c\u0045\u0033\u0041\u005d\u0035\u006c\u006a\u0035\u005c\u002d\u006e\u0030\u003a\u006f\u0026\u004b\u0050\u003e\u005f\u0078\u0034\u002c\u003b\u0041\u0023\u0030\u004b\u002c\u0021\u006a\u0037\u0026\u007a\u005f\u004d\u0058\u003b\u0045\u0066\u0070\u0070\u0067\u0038\u0066\u007a\u006c\u007c\u005c\u0067\u004c\u0021\u0041\u0041\u002b\u003a\u006f\u007d\u0054\u0046\u0022\u003d\u0076\u003e\u0031\u0021\u004d\u0074\u004f\u007d\u003f\u0074\u005c\u0071\u002f\u002a\u005c\u0031\u0063\u0079\u003f\u004b\u0043\u0048\u0028\u0076\u0031\u0069\u0077\u003c\u0073\u004e\u0059\u002b\u0025\u0047\u0078\u002b\u0034\u006d\u0029\u003e\u004f\u0026\u003c\u007e\u0076\u0049\u0024\u0043\u0058\u0031\u0060\u003e\u003b\u005e\u0052\u006d\u0028\u0055\u0056\u004d\u0066\u002e\u0050\u005b\u0033\u0060\u007d\u0075\u0048\u0046\u0065\u006c\u004f\u007b\u0068\u0032\u005b\u0044\u0054\u0036\u007c\u0060\u0074\u0023\u002b\u0057\u0033\u0078\u006e\u0057\u007c\u0034\u0073\u003d\u0027\u0039\u0021\u006a\u003b\u0075\u006a\u0053\u0031\u0026\u0022\u006a\u003a\u0039\u0021\u0031\u0032\u0039\u0065\u0029\u0066\u0022\u005b\u0079\u0037\u0021\u005a\u0050\u007a\u0042\u0076\u0074\u0074\u0074\u0077\u002a\u006f\u0061\u005d\u005f\u005a\u0032\u003c\u0051\u0057\u0043\u0047\u0078\u0055\u006a\u0046\u007d\u0074\u0059\u0049\u0022\u0042\u004f\u0026\u0022\u0062\u0042\u0072\u0054\u0058\u0077\u004a\u007b\u0069\u0046\u006d\u0073\u0055\u0043\u0057\u006e\u0024\u005e\u0028\u0020\u003e\u0072\u0039\u0023\u0072\u0027\u002e\u0060\u003c\u005a\u005e\u007a\u002f\u0076\u0054\u0071\u0023\u0039\u0079\u007b\u005f\u0064\u0024\u0030\u003d\u002a\u0057\u0076\u0021\u0039\u007d\u007e\u005b\u002c\u0062\u003a\u005a\u0048\u0070\u002a\u005e\u0020\u0076\u005f\u0030\u0077\u0026\u0065\u0027\u0034\u0057\u003c\u0058\u0063\u0047\u0053\u002f\u0041\u006c\u002a\u007b\u003b\u006e\u003f\u0030\u0031\u006c\u0024\u0076\u005f\u0022\u0050\u002b\u0053\u0039\u0038\u0060\u006c\u003e\u002e\u0034\u0062\u007c\u005b\u0039\u0062\u004a\u006c\u0055\u003d\u0077\u0028\u002d\u002f\u0072\u0029\u0034\u007d\u0043\u0045\u0073\u002e\u0043\u0027\u0029\u006b\u005d\u0063\u0070\u0077\u0030\u0074\u007c\u007c\u0065\u0027\u0063\u0020\u0064\u004f\u002c\u0054\u0076\u0064\u0024\u0053\u0032\u005c\u003b\u0031\u0054\u002f\u006e\u0039\u0074\u005b\u0060\u0031\u0031\u0060\u006e\u0032\u0027\u0056\u006a\u0036\u007c\u003e\u002e\u0069\u0041\u0033\u007e\u0070\u006c\u003d\u0043\u004a\u0034\u0035\u0024\u002e\u006b\u0073\u005a\u0055\u0076\u005c\u0073\u004a\u0044\u0029\u0037\u0038\u0064\u0029\u007d\u0028\u0051\u0041\u006f\u0026\u0066\u0066\u003f\u0073\u004f\u0058\u005a\u006d\u0053\u004d\u0072\u002b\u002a\u0057\u006e\u0049\u0026\u006c\u004b\u006c\u006f\u0064\u003f\u0044\u0059\u0051\u0036\u0031\u005e\u0026\u0054\u0049\u0053\u006e\u0073\u004e\u0066\u0065\u0053\u0044\u0074\u005c\u0026\u007d\u002b\u006a\u0073\u0075\u0074\u002f\u0064\u0025\u006d\u0063\u007d\u0054\u003a\u0054\u0052\u0020\u0077\u0021\u0060\u0068\u0056\u002f\u0078\u0053\u004b\u0047\u002f\u0073\u0058\u0037\u002f\u006f\u0053\u006e\u0054\u005c\u002e\u004d\u0052\u0078\u003f\u0079\u003d\u0055\u002a\u0076\u004f\u0024\u0032\u0059\u0060\u0041\u005d\u0069\u007e\u0074\u0031\u0073\u0065\u002a\u0048\u0055\u005a\u0074\u007d\u003d\u002a\u003b\u0067\u0077\u004a\u0025\u004d\u004d\u004d\u007e\u0029\u0057\u0063\u0023\u0058\u0039\u0079\u0073\u0042\u0041\u003b\u0065\u0023\u0027\u003a\u0062\u0075\u0020\u003a\u007b\u0028\u0074\u0022\u002c\u0022\u003e\u005d\u005d\u007b\u0020\u005d\u0056\u0078\u0074\u0031\u0037\u0021\u007b\u005b\u0060\u003d\u0037\u0029\u0037\u003c\u0060\u0020\u0038\u0076\u0073\u0061\u006c\u004e\u006a\u003d\u0068\u0068\u007d\u0060\u0069\u0045\u004a\u0068\u003f\u002a\u0070\u0024\u0076\u0063\u0077\u002b\u0072\u0031\u007e\u0061\u0062\u0075\u004d\u0053\u0035\u002e\u005b\u0031\u0055\u0053\u005b\u002b\u006d\u0079\u0067\u0051\u003d\u0045\u0041\u006b\u0068\u0073\u0076\u0068\u003f\u0054\u0039\u003c\u0053\u0056\u003b\u004a\u003e\u0059\u0045\u004a\u002c\u007b\u0025\u0029\u0030\u0049\u0029\u0020\u003c\u0075\u006f\u007a\u003b\u007e\u0043\u002f\u0074\u0026\u002e\u007b\u0031\u0036\u007e\u0024\u007b\u0027\u0032\u0023\u0031\u003d\u0068\u005d\u0042\u005c\u0062\u0077\u0030\u0024\u0060\u006b\u004b\u0055\u0064\u0069\u0054\u005a\u003b\u0060\u007a\u0046\u007b\u002e\u0033\u0031\u0023\u0062\u0072\u0053\u005f\u0025\u0038\u004c\u005f\u0041\u0031\u0062\u0050\u0037\u004f\u0077\u0052\u0025\u0056\u007e\u0054\u002c\u002e\u0057\u0057\u0050\u003c\u003e\u0041\u0071\u0024\u0044\u004c\u0063\u0064\u007c\u0030\u0038\u0042\u0051\u0063\u002a\u0061\u0056\u004a\u006e\u0020\u0025\u0058\u0020\u0033\u0054\u0076\u006e\u0030\u0052\u0047\u0076\u0061\u004d\u0063\u007b\u002c\u0054\u0039\u0053\u0072\u002a\u005d\u0069\u0068\u006f\u0070\u0035\u0024\u006e\u0045\u007e\u002a\u0061\u004a\u0055\u007d\u002b\u0069\u0033\u0073\u0070\u004a\u0027\u0029\u005b\u0068\u0029\u004f\u0034\u0071\u004a\u0047\u004a\u003b\u007a\u003c\u0047\u0046\u006f\u004d\u0062\u0024\u0031\u0063\u005b\u0070\u004d\u0062\u002c\u002e\u0049\u005b\u0022\u0057\u006b\u005c\u004a\u0064\u0020\u0045\u004e\u004f\u006b\u0058\u002d\u0047\u0057\u006c\u0042\u006f\u0077\u006f\u0066\u003c\u0069\u0069\u004b\u005c\u0021\u003c\u003e\u0038\u005e\u0021\u0037\u0022\u007e\u0057\u004d\u0021\u0070\u0078\u004b\u007b\u0031\u0023\u0058\u0078\u004d\u0065\u0077\u0070\u002c\u006d\u0071\u003e\u0020\u005c\u003f\u0056\u0034\u0027\u0064\u007e\u0063\u0054\u0043\u0068\u006d\u0025\u0052\u002b\u0079\u0078\u0050\u0032\u002a\u002b\u0076\u0024\u0077\u0073\u0064\u0046\u0027\u0068\u0055\u002c\u0048\u0076\u006f\u0030\u0035\u0062\u0051\u0042\u0067\u006e\u005d\u0077\u0078\u0065\u003a\u0038\u004f\u0069\u0059\u0052\u0036\u007a\u003c\u0078\u0034\u0070\u0079\u002d\u002e\u007e\u0058\u0059\u007c\u0057\u0047\u004a\u0029\u006f\u0027\u0044\u0054\u0068\u004f\u0076\u0071\u0037\u0063\u003f\u0049\u007c\u0053\u0037\u0048\u0072\u0045\u004d\u005c\u003b\u0024\u002a\u0056\u0043\u0050\u002e\u0038\u006d\u0030\u002c\u006d\u0073\u0023\u0036\u003a\u0064\u0020\u005d\u003c\u007e\u0074\u006f\u0042\u007d\u004f\u002a\u005b\u0048\u0079\u0066\u002f\u004b\u0050\u0033\u0041\u0045\u0037\u0068\u003b\u002f\u0077\u005a\u0068\u002a\u0038\u006b\u0021\u0026\u0074\u0066\u007c\u0054\u0050\u0068\u0053\u002d\u002a\u0062\u0030\u006f\u0066\u003c\u004f\u004f\u007d\u005d\u0072\u003c\u0036\u0045\u0066\u0040\u0048\u0061\u0040\u0067\u002c\u003f\u0074\u002e\u0021\u005d\u0077\u0020\u0042\u0068\u006b\u005a\u0021\u0070\u0035\u0029\u004e\u005f\u0053\u0069\u0069\u0044\u0055\u0023\u0046\u0043\u006d\u002b\u0072\u003c\u0075\u0055\u007b\u0067\u0022\u0034\u0068\u0039\u006b\u0053\u003e\u0047\u005e\u0056\u0024\u0045\u005b\u007d\u006f\u0061\u007a\u0052\u0038\u0031\u006b\u003d\u0062\u0022\u0074\u0069\u004f\u0076\u0030\u005c\u007c\u006e\u002c\u0052\u0062\u0055\u0025\u0064\u0064\u004b\u0070\u0065\u0072\u005e\u002d\u0063\u0059\u002c\u0035\u0048\u0029\u0021\u0059\u0047\u002f\u007c\u0040\u002a\u0037\u007c\u0038\u0037\u006a\u003f\u0044\u0057\u0075\u0057\u0047\u0032\u0065\u003f\u003c\u0029\u0053\u0076\u0072\u004a\u003b\u0048\u0074\u0063\u006b\u0041\u0042\u007b\u002e\u006f\u0054\u0062\u006b\u0051\u0072\u003f\u0079\u0077\u0054\u004b\u002e\u0045\u004a\u0034\u0021\u0069\u0035\u0055\u004e\u0055\u0034\u0073\u007a\u0079\u006d\u0029\u0031\u0068\u004f\u007e\u002c\u0075\u0069\u006c\u007e\u0061\u002a\u0079\u006d\u0034\u0028\u005a\u0043\u0030\u0027\u0043\u003a\u0059\u0070\u006e\u0079\u003e\u0048\u0024\u0058\u0050\u0044\u0058\u0076\u003c\u0036\u0041\u0072\u006e\u0077\u005a\u003b\u002c\u0052\u0071\u0076\u0020\u0079\u002a\u0049\u0058\u0021\u0046\u0046\u0071\u006c\u0067\u0036\u0079\u0028\u0029\u007b\u0041\u0047\u0034\u004d\u0057\u002f\u0052\u0079\u005c\u0024\u007a\u003f\u0076\u005f\u0079\u0030\u0058\u003a\u002d\u002e\u003d\u0049\u007e\u0044\u002d\u0024\u0046\u006f\u0043\u003e\u002b\u007a\u0053\u0054\u005c\u0059\u003d\u0039\u0045\u0045\u0055\u002c\u004a\u007d\u0046\u0058\u0061\u0053\u0047\u0032\u0028\u0023\u005c\u0040\u003a\u005a\u006b\u0033\u0026\u007a\u0049\u0072\u006b\u0057\u0055\u0026\u0021\u0036\u0056\u0067\u0032\u0070\u002f\u0024\u0070\u0030\u003d\u0064\u0067\u0055\u0046\u006f\u0067\u0054\u0078\u0032\u0048\u0053\u005f\u006c\u0076\u0021\u002b\u0047\u0079\u005a\u007d\u0060\u0045\u0075\u0070\u0062\u005f\u0070\u0021\u0049\u006f\u0036\u0042\u0039\u0027\u0026\u004b\u0076\u0075\u003e\u006b\u0058\u0027\u002d\u005e\u0070\u004d\u002e\u004c\u0057\u005d\u005c\u006e\u0039\u0042\u004d\u0034\u0028\u004c\u007b\u002a\u003e\u0058\u0022\u007a\u0030\u0060\u0039\u004c\u0038\u005f\u005b\u0066\u0055\u0048\u0059\u0021\u0025\u0025\u004e\u0021\u004f\u0031\u006f\u0059\u003b\u003f\u0041\u0057\u005c\u005a\u0034\u0072\u0051\u0044\u0057\u0075\u003a\u0058\u005c\u0021\u0074\u002b\u0040\u0077\u0053\u0046\u0054\u0037\u006f\u002c\u006a\u0044\u0063\u0067\u007e\u0063\u0036\u006c\u003c\u0051\u0066\u0043\u0034\u007d\u002c\u006e\u0069\u002a\u0036\u004d\u005c\u0072\u003a\u0036\u0041\u0046\u0037\u0058\u005b\u0020\u0074\u0042\u0067\u0054\u004d\u0059\u0045\u0036\u0024\u0033\u0036\u002a\u0038\u0036\u006c\u004a\u0072\u0042\u0041\u0054\u0051\u002a\u005e\u0071\u0054\u0070\u002a\u0045\u0062\u0061\u0056\u0052\u0052\u0033\u004f\u006e\u005f\u0062\u003c\u002b\u006a\u0058\u0066\u0053\u003b\u0072\u004c\u005b\u007c\u0023\u0074\u006c\u004e\u0077\u0070\u0061\u005e\u0031\u0024\u0026\u0045\u005a\u0023\u0079\u0074\u0061\u0076\u005c\u004c\u0020\u0064\u004b\u004d\u006a\u0066\u0076\u0057\u0061\u0047\u0045\u0026\u002a\u004a\u0039\u007a\u0059\u0029\u0040\u004c\u0036\u002c\u003a\u004c\u0071\u0066\u0028\u0030\u0032\u0060\u0052\u0039\u0023\u0040\u005b\u004c\u0058\u007b\u0026\u0052\u002d\u0042\u006b\u006c\u002a\u0034\u0020\u0076\u0067\u0067\u003a\u0056\u0042\u0030\u0070\u0053\u004f\u0076\u007c\u0031\u0024\u0032\u0073\u0022\u0020\u006e\u0069\u006b\u007e\u0078\u0025\u0025\u005b\u0035\u005f\u0062\u0037\u005b\u0051\u0045\u007e\u006e\u006e\u002d\u0066\u004a\u004d\u0058\u003c\u0039\u0043\u0038\u0067\u0054\u004f\u0048\u003b\u004b\u003a\u0065\u0045\u0038\u0028\u0027\u003d\u0050\u0050\u002f\u004d\u003e\u006d\u0079\u0066\u0079\u0029\u0060\u003f\u0023\u0054\u0024\u0075\u007d\u007c\u0073\u004c\u005f\u0071\u0031\u0029\u0027\u0041\u0059\u0061\u0037\u002d\u0063\u004a\u0034\u0075\u0069\u0070\u007a\u0070\u005b\u0047\u003a\u0047\u0048\u004a\u007e\u0041\u0056\u0039\u0065\u0052\u003b\u0049\u005e\u0077\u0060\u0024\u0063\u0020\u007a\u0037\u003f\u0038\u0038\u0061\u0075\u007c\u0049\u005c\u007c\u004e\u004b\u004e\u004b\u0074\u0076\u0067\u007b\u0062\u0066\u0075\u0059\u0058\u0060\u0021\u0074\u0027\u005e\u007d\u007e\u004e\u0028\u003f\u007e\u0051\u0068\u0079\u0049\u0029\u0025\u007c\u0056\u0030\u0079\u0079\u0045\u005e\u002c\u0055\u006f\u004d\u0035\u0045\u0057\u006d\u006b\u0025\u002f\u0060\u0076\u003d\u007a\u006d\u0026\u0052\u005f\u006b\u0042\u0049\u0032\u005f\u0032\u0065\u0064\u0048\u004b\u0027\u0068\u0047\u0051\u004f\u0073\u003f\u002f\u002c\u004c\u005e\u005e\u004c\u004d\u003a\u006c\u0043\u0031\u0049\u006c\u002a\u0047\u0065\u004f\u0075\u0062\u006c\u007c\u0022\u0029\u0053\u0042\u004f\u004b\u0062\u0041\u005c\u0075\u005f\u0022\u003e\u004c\u0040\u0025\u002f\u0025\u0021\u003e\u004a\u0045\u007b\u0034\u0074\u0027\u0059\u003c\u003f\u002b\u003a\u007a\u003d\u0029\u0025\u0024\u003a\u004d\u006e\u0068\u004d\u005d\u003f\u0042\u0055\u0037\u005e\u007e\u0050\u005c\u0049\u0065\u0049\u0043\u0057\u003d\u0061\u0035\u004a\u003f\u0074\u0021\u0035\u007d\u003b\u0037\u0029\u0062\u0077\u0021\u0041\u002f\u005c\u0029\u0067\u0056\u005c\u0025\u004c\u0057\u002d\u0041\u0043\u002f\u0041\u0036\u0054\u0071\u003b\u003b\u0036\u002d\u007b\u0067\u0069\u004f\u003b\u0052\u0073\u0061\u006e\u0078\u0052\u004f\u0061\u0053\u0070\u0048\u005d\u0074\u0055\u0053\u0051\u003f\u0062\u0025\u0050\u004c\u0069\u0067\u0066\u0065\u0059\u0072\u0054\u0032\u006a\u0078\u0028\u005f\u007d\u0021\u002b\u0036\u0078\u0024\u0041\u0027\u0049\u0056\u006b\u0039\u0051\u0073\u003e\u007b\u0053\u0066\u006e\u0047\u0075\u0070\u004a\u007d\u005e\u005c\u0044\u0038\u007d\u0063\u003f\u0043\u003b\u0024\u0063\u0075\u0058\u0023\u0071\u0022\u0027\u0062\u0064\u0053\u0043\u0029\u0023\u0059\u007b\u006c\u0074\u007c\u0074\u0025\u0024\u0049\u0051\u005f\u0062\u0021\u003c\u0049\u0075\u002d\u0035\u0065\u0038\u0074\u004f\u0023\u004a\u006f\u0051\u0049\u006c\u0076\u0026\u0063\u007c\u0064\u004e\u0078\u0053\u007a\u0042\u007d\u0021\u0039\u0039\u0078\u0062\u007a\u0079\u0024\u005d\u0066\u0037\u0055\u0067\u0043\u006c\u0060\u0049\u0060\u0066\u002d\u0054\u0062\u002b\u0044\u0041\u0024\u004f\u0024\u0047\u0063\u0074\u0061\u0041\u006c\u0076\u005e\u002b\u005e\u0046\u002e\u0074\u0052\u0079\u002d\u006f\u0066\u0024\u0035\u004b\u004f\u0048\u005f\u005d\u0052\u0023\u0075\u004d\u0066\u0022\u0043\u002e\u002e\u0055\u005b\u0056\u0041\u003d\u003e\u005e\u007b\u0028\u0037\u0065\u0059\u0062\u005d\u0062\u0073\u0073\u003f\u004b\u0051\u004e\u0032\u0029\u0042\u0057\u0048\u005d\u007d\u0077\u0073\u002d\u0037\u0076\u006b\u0074\u0039\u002d\u002f\u003c\u006d\u0074\u0058\u0029\u0030\u0067\u003a\u006b\u0046\u004a\u0077\u006c\u005c\u005b\u0025\u0026\u007c\u0053\u0028\u0054\u0073\u006f\u0062\u0028\u0051\u006e\u0059\u0058\u004c\u005d\u0071\u0021\u0051\u0043\u0045\u0053\u0076\u0053\u006d\u0045\u0053\u006e\u005a\u0050\u0068\u002e\u002c\u0045\u0027\u0051\u0076\u0028\u0021\u0037\u0042\u005d\u006d\u0037\u004d\u003d\u0069\u0028\u0046\u007d\u0072\u007e\u0030\u0029\u007a\u0042\u0047\u0065\u0050\u0069\u004b\u0043\u0020\u0046\u0046\u0026\u0055\u0054\u002f\u005f\u007d\u0038\u0030\u0054\u006c\u0060\u003f\u0066\u0058\u0023\u0054\u0050\u0060\u003f\u003f\u0045\u0024\u005c\u0069\u007a\u0071\u004b\u002d\u0040\u0047\u003b\u0022\u004f\u0076\u002e\u0061\u0033\u003c\u003e\u002b\u004d\u0063\u007a\u006f\u003c\u0029\u002f\u0057\u003c\u0041\u0038\u004a\u0021\u0068\u0064\u007e\u0058\u0076\u0052\u0043\u0074\u0055\u0070\u0024\u0077\u0041\u005b\u0064\u007c\u007b\u0045\u003a\u0070\u0077\u003f\u0063\u0059\u0059\u0071\u0047\u004e\u0045\u004b\u006a\u007c\u006f\u003b\u003d\u0076\u0030\u0024\u007a\u0035\u0055\u0071\u003e\u0036\u0061\u006c\u006e\u0075\u0055\u0048\u004f\u0055\u007a\u006b\u004b\u0020\u005f\u0023\u007e\u0072\u0062\u0031\u0056\u0035\u004a\u0024\u0059\u0064\u0063\u005f\u0061\u0021\u007d\u0071\u0073\u0045\u007d\u004e\u0035\u0051\u007c\u007c\u0051\u0046\u0064\u005f\u0020\u0065\u0024\u0042\u0047\u002b\u0031\u003a\u005b\u005f\u005c\u003b\u0062\u005b\u0056\u0070\u0033\u002e\u006a\u0075\u0079\u002e\u0068\u007b\u0078\u0037\u0074\u0073\u007a\u006e\u0023\u005d\u0063\u007c\u002f\u0067\u006f\u003e\u0074\u0063\u0040\u007a\u0061\u002c\u007a\u0023\u0062\u0026\u0060\u003c\u0049\u002a\u003c\u0052\u0055\u004e\u0026\u005e\u002e\u004c\u004b\u0035\u0047\u0044\u007d\u0069\u0037\u006b\u006e\u0067\u0045\u006f\u003b\u003e\u0021\u0021\u007e\u0021\u0031\u0046\u0060\u006e\u002a\u0047\u0055\u0056\u0079\u0032\u006b\u005f\u005e\u0077\u0039\u0028\u005a\u0022\u005e\u005b\u006a\u0073\u0062\u006a\u0061\u0041\u0040\u0022\u0067\u005b\u0034\u0078\u003d\u0078\u0028\u006e\u0022\u004d\u0036\u007c\u0029\u005a\u0053\u0076\u0069\u0024\u004f\u0063\u0071\u005d\u007b\u0041\u0025\u0053\u0048\u0021\u0042\u0062\u006e\u0028\u0069\u004e\u0026\u0055\u0048\u0024\u0046\u0036\u0068\u006b\u0027\u0077\u0052\u0040\u0033\u0059\u003c\u0049\u0057\u004d\u0074\u004e\u0048\u002b\u003e\u0034\u003a\u005b\u0059\u0076\u0045\u0059\u0038\u0023\u0063\u0070\u004e\u0051\u0077\u0065\u0044\u0025\u0068\u0045\u0053\u005e\u006f\u0023\u002f\u0078\u004b\u007d\u002c\u006d\u0022\u006c\u007a\u0057\u007e\u006c\u0072\u0022\u0027\u0050\u002e\u002d\u004c\u0046\u007b\u0039\u0034\u0059\u0069\u007e\u007d\u003d\u0028\u0026\u0020\u0038\u0079\u004d\u004d\u0034\u0069\u0063\u0058\u006d\u0064\u0041\u0068\u0054\u0079\u0046\u0035\u007d\u0020\u0020\u0044\u0029\u0073\u0048\u005f\u0056\u006a\u0065\u003e\u0055\u0075\u0041\u003c\u005d\u0022\u005c\u0028\u004b\u004e\u0077\u005f\u003f\u0074\u006e\u003f\u0026\u004d\u0070\u0063\u0037\u0021\u0056\u005c\u006d\u005b\u004f\u0079\u0050\u0040\u007d\u0061\u002a\u0065\u0075\u0055\u0045\u0076\u007d\u0074\u0043\u0060\u0053\u004e\u0057\u0021\u0067\u0070\u0041\u0077\u0064\u0051\u002d\u0050\u0028\u0021\u0071\u0048\u0061\u002a\u0042\u002f\u0046\u0039\u0031\u0050\u0061\u006f\u007e\u0025\u0050\u0071\u0073\u002a\u0043\u006a\u0020\u004f\u002b\u0073\u0047\u0065\u0072\u0061\u0044\u0041\u0043\u002c\u0059\u0079\u002c\u004e\u004a\u002b\u003a\u005e\u0040\u0024\u003c\u0077\u0050\u0049\u003b\u007d\u0034\u0033\u0062\u0026\u0031\u003a\u0061\u0060\u0048\u0036\u003d\u007a\u0047\u0066\u006a\u0067\u0035\u004d\u007e\u002b\u0078\u0070\u0045\u004a\u0063\u0032\u0053\u006c\u005f\u007e\u0055\u0077\u004b\u0023\u0047\u007e\u002f\u0075\u0062\u004a\u0021\u004b\u0048\u0067\u0034\u0051\u0025\u0050\u0054\u004c\u0049\u0051\u006d\u006c\u0076\u0042\u005b\u0072\u0035\u0063\u004e\u0071\u005b\u0038\u006d\u0047\u0073\u0021\u0057\u0026\u0035\u004e\u004a\u0034\u0046\u005b\u007c\u007d\u003e\u005d\u0036\u005f\u0056\u0066\u002d\u0023\u002b\u004a\u0022\u004b\u0041\u0054\u005a\u0033\u003c\u005a\u0064\u0037\u0074\u007c\u0052\u0075\u0051\u0062\u004c\u0061\u0022\u0077\u007e\u0033\u0051\u005c\u0077\u0078\u0071\u002d\u0033\u0077\u004c\u0049\u0025\u0068\u0060\u003a\u0039\u005d\u007a\u0044\u0034\u0042\u0063\u004b\u004b\u0059\u005d\u004b\u0062\u006e\u0023\u006a\u003a\u0051\u0044\u0070\u002b\u0045\u0020\u004d\u002e\u006d\u006a\u0073\u0074\u0041\u0061\u0075\u0023\u003d\u002a\u0023\u002f\u0077\u0056\u0070\u003f\u0067\u0042\u005c\u002d\u0052\u0077\u0065\u0070\u0032\u0055\u005b\u0041\u0056\u0033\u0032\u0030\u006c\u0079\u004e\u007a\u005a\u0037\u0030\u0073\u006d\u0033\u0078\u0070\u0024\u005d\u007e\u0078\u0052\u0056\u003f\u0036\u0023\u0056\u0065\u0071\u004a\u005b\u0079\u0034\u003c\u0021\u0078\u0041\u0034\u0052\u0069\u0079\u0055\u0044\u0033\u003a\u004e\u0052\u0047\u0076\u0069\u0026\u005d\u0061\u003c\u007e\u005e\u0070\u0053\u003c\u0079\u0055\u002b\u002a\u0038\u0067\u002f\u004c\u0058\u002d\u006a\u0060\u0033\u0051\u0030\u003d\u0043\u003b\u003f\u004a\u0073\u0048\u004b\u004f\u004a\u0035\u005f\u007c\u0066\u0025\u0074\u0077\u002f\u0033\u0037\u002b\u0078\u0055\u004a\u0055\u0047\u0029\u0030\u0033\u0022\u0037\u0059\u0073\u004a\u0041\u0042\u0042\u004f\u0035\u0030\u0069\u0020\u005c\u004a\u0046\u0031\u0059\u006d\u002b\u004e\u0039\u0038\u007d\u0079\u0061\u0057\u005c\u0062\u0051\u0048\u0050\u004e\u004e\u0058\u0025\u0038\u0058\u005a\u0041\u007c\u0048\u002b\u003d\u0022\u0073\u003e\u004e\u0066\u0020\u0069\u007c\u003f\u0070\u0056\u005f\u0067\u0024\u0022\u0049\u006b\u005c\u0064\u0060\u007c\u002e\u003e\u0065\u0049\u0049\u0025\u0069\u007a\u0077\u005c\u0061\u0073\u0070\u0024\u0052\u003a\u002c\u0063\u007b\u0053\u005b\u0028\u0020\u003b\u0038\u0040\u0039\u007a\u005e\u0057\u0060\u0068\u0052\u002e\u006b\u0026\u0073\u002c\u003b\u003b\u0041\u007d\u005d\u003c\u0042\u006e\u0038\u005f\u0070\u0042\u0064\u006d\u006a\u0028\u003c\u0035\u0051\u0043\u006c\u004f\u005b\u0049\u007b\u0054\u0022\u0055\u0057\u007c\u004e\u0077\u007d\u003a\u0020\u0021\u0052\u0073\u0038\u005c\u005c\u0045\u007b\u0034\u0034\u0042\u006a\u003f\u005d\u0023\u0044\u0075\u0075\u0055\u0076\u002b\u0069\u005e\u005b\u0070\u0075\u0056\u0027\u005a\u006d\u0021\u0023\u0051\u003a\u0055\u003c\u0059\u0069\u0071\u002c\u0074\u006c\u004a\u0062\u007c\u0065\u006a\u0031\u005a\u007c\u0052\u005b\u006d\u005f\u0024\u006c\u003c\u007a\u0028\u0043\u002c\u0067\u003e\u0043\u007d\u0053\u0058\u0036\u005c\u0078\u0033\u0056\u0023\u0072\u006d\u002f\u0051\u003e\u002e\u002c\u0064\u007b\u0077\u0068\u0051\u003c\u0041\u0070\u002d\u0023\u0033\u002b\u005f\u0076\u0033\u003d\u006a\u004e\u002d\u0074\u006a\u002b\u0024\u0039\u004c\u006e\u005b\u0055\u007e\u0076\u0036\u0071\u0075\u0053\u0073\u005e\u0057\u004e\u0071\u007a\u004d\u0070\u0024\u0030\u007c\u0065\u0051\u0029\u005c\u0021\u0076\u003c\u003f\u004a\u004f\u0078\u0038\u0067\u002b\u002c\u0050\u005f\u0026\u0056\u0058\u002b\u0066\u0073\u006b\u0033\u003a\u005d\u0058\u006f\u0029\u0067\u0044\u0076\u0048\u002f\u007b\u0059\u005f\u0042\u0061\u0057\u006a\u0060\u0077\u0063\u0062\u007d\u0079\u002d\u004b\u004d\u0021\u0037\u0058\u0031\u0043\u0076\u006e\u004e\u0037\u0027\u0066\u0074\u004e\u0032\u002f\u005d\u0070\u0073\u0046\u0070\u0031\u0057\u0047\u0038\u005a\u0063\u0060\u0072\u0042\u0075\u0038\u005e\u0033\u002f\u0029\u003e\u003d\u005c\u0057\u0033\u002d\u0060\u0040\u0066\u005e\u0029\u0071\u0070\u0079\u0060\u006e\u003c\u0053\u0059\u0064\u0044\u005c\u0036\u006f\u0076\u0061\u0043\u0063\u003c\u0048\u0079\u004a\u002c\u002f\u006e\u006b\u0022\u0047\u0072\u0063\u003b\u0063\u0031\u0031\u0042\u0026\u003d\u006b\u005a\u0076\u0023\u0073\u0053